changeSet.sql:
UPDATE clinlims.notebook_page np SET page_order = 11, last_updated = ${now} FROM clinlims.notebook n WHERE np.notebook_id = n.id AND n.workflow_type = 'mntd' AND n.is_template = false AND np.title = 'Reporting & REDCap Integration';
UPDATE clinlims.notebook_page np SET page_order = 10, last_updated = NOW() FROM clinlims.notebook n WHERE np.notebook_id = n.id AND n.workflow_type = 'mntd' AND n.is_template = false AND np.title = 'Data Analysis & Export';
INSERT INTO clinlims.notebook_page ( id, title, instructions, content, page_order, completed, page_type, notebook_id, last_updated ) SELECT nextval('notebook_page_seq'), template_page.title, template_page.instructions, template_page.content, template_page.page_order, false, template_page.page_type, child.id, NOW() FROM clinlims.notebook child JOIN clinlims.notebook template ON template.title = 'Malaria and Neglected Tropical Disease (MNTD) Laboratory' AND template.is_template = true JOIN clinlims.notebook_page template_page ON template_page.notebook_id = template.id AND template_page.title = 'Sample Archiving' WHERE child.workflow_type = 'mntd' AND child.is_template = false AND NOT EXISTS ( SELECT 1 FROM clinlims.notebook_page existing WHERE existing.notebook_id = child.id AND existing.title = 'Sample Archiving' );

SELECT setval('clinlims.workflow_page_template_seq',
    COALESCE((SELECT MAX(id) FROM clinlims.workflow_page_template), 0) + 1,
    false);

UPDATE clinlims.workflow_page_template
SET display_order = 11
WHERE workflow_category = 'MNTD' AND name = 'Reporting & REDCap Integration';

UPDATE clinlims.workflow_page_template
SET display_order = 10
WHERE workflow_category = 'MNTD' AND name = 'Data Analysis & Export';
